```typescript
class RequestQueue {
  private queue: OrchestrationRequest[] = [];
  private processing = false;
  private concurrencyLimit = 5;
  private activeRequests = 0;

  async enqueue(request: OrchestrationRequest): Promise<OrchestrationResponse> {
    return new Promise((resolve, reject) => {
      this.queue.push({
        ...request,
        resolve,
        reject
      });
      this.processQueue();
    });
  }

  private async processQueue() {
    if (this.processing || this.activeRequests >= this.concurrencyLimit) return;
    this.processing = true;

    while (this.queue.length > 0 && this.activeRequests < this.concurrencyLimit) {
      const request = this.queue.shift();
      this.activeRequests++;
      this.processRequest(request);
    }

    this.processing = false;
  }
}
```
